public static List<Interval> condenseIntervals(Iterable<Interval> intervals)
{
  final SortedSet<Interval> sortedIntervals = new TreeSet<>(Comparators.intervalsByStartThenEnd());

  for (Interval interval : intervals) {
    // Zero-length intervals do not cover any time, so they are not useful in a condensed list.
    if (!Intervals.isEmpty(interval)) {
      sortedIntervals.add(interval);
    }
  }

  return ImmutableList.copyOf(condensedIntervalsIterator(sortedIntervals.iterator()));
}

